# --- Génération Stimuli  ---
generer_donnees <- function(n, type, seed_hauteurs) {
  n <- as.numeric(n)
  pool <- seq(10, 90, by = 0.5)   
  if (type == "Uniform") {
    return(seq(15, 85, length.out = n))
  }

  if (type == "Gaussian") {
    poids <- dnorm(pool, mean = 50, sd = 20.21)

  } else if (type == "Trimodal T") {
    poids <- 0.33 * dnorm(pool, 25.7, 1.5) + 0.33 * dnorm(pool, 58, 1.5) + 0.34 * dnorm(pool, 74.3, 1.5)

  } else if (type == "Trimodal S") {
    poids <- 0.33 * dnorm(pool, 25.7, 1.5) + 0.33 * dnorm(pool, 42, 1.5) + 0.34 * dnorm(pool, 74.3, 1.5)
  }

  set.seed(seed_hauteurs) 
  valeurs <- sample(pool, size = n, replace = FALSE, prob = poids / sum(poids))
  return(valeurs)
}

