server <- function(input, output, session) {
  rv <- reactiveValues(phase = "welcome", trial = 1, start_time = NULL, current_data = NULL, results = data.frame(), trial_list = NULL, show_error = FALSE, click_history = c(), part_id = NULL, condition = NULL, age = NULL, sex = NULL, nationality = NULL)

  output$phase <- renderText({ rv$phase })
  outputOptions(output, "phase", suspendWhenHidden = FALSE)

  output$dynamic_instruction <- renderUI({ 
    txt <- ifelse(rv$condition == "tall", "Select the tall rectangles.", "Select the tallest rectangles.")
    h2(txt) 
  })

  observe({ 
    query <- parseQueryString(session$clientData$url_search)
    if (!is.null(query[['PROLIFIC_PID']])) { rv$part_id <- query[['PROLIFIC_PID']] } else { rv$part_id <- paste0("TEST_", sample(1000:9999, 1)) }
    if (is.null(rv$condition)) { rv$condition <- sample(c("tall", "tallest"), 1) } 
  })

  observeEvent(input$go_setup_btn, {
    rv$phase <- "setup"
  })

  observeEvent(input$start_btn, { 
    if (is.na(input$age) || input$sex == "" || trimws(input$nationality) == "") { rv$show_error <- TRUE } 
    else { 
      rv$age <- input$age; rv$sex <- input$sex; rv$nationality <- input$nationality; rv$show_error <- FALSE
      shapes <- c("Uniform", "Gaussian", "Trimodal T", "Trimodal S"); orders <- c("shuffled", "ordered"); sizes  <- c(12, 24, 36, 48)
      design <- expand.grid(shape = shapes, order = orders, size = sizes)
      rv$trial_list <- design[sample(nrow(design)), ]; rv$phase <- "selection" 
    } 
  })

  output$setup_warning <- renderUI({ if (rv$show_error && rv$phase == "setup") div(class="error-msg", "Please fill in all fields to continue.") })

  observe({ 
    if (rv$phase == "selection" && is.null(rv$current_data)) { 
      trial_info <- rv$trial_list[rv$trial, ]; hauteurs <- generer_donnees(trial_info$size, trial_info$shape, 1000 + rv$trial)
      if (trial_info$order == "ordered") hauteurs <- sort(hauteurs) else hauteurs <- sample(hauteurs)
      rangs <- rank(hauteurs)
      rv$current_data <- data.frame(id = 1:length(hauteurs), height = hauteurs, size_rank = rangs, selected = FALSE, display_pos = 1:length(hauteurs))
      rv$click_history <- c(); rv$start_time <- Sys.time(); rv$show_error <- FALSE 
    } 
  })

  observeEvent(input$plot_click, { 
    req(rv$current_data); pos <- round(input$plot_click$x); val_y <- input$plot_click$y
    if (pos %in% rv$current_data$display_pos) { 
      idx <- which(rv$current_data$display_pos == pos)
      if (val_y <= rv$current_data$height[idx]) { 
        rv$current_data$selected[idx] <- !rv$current_data$selected[idx]
        if (rv$current_data$selected[idx]) { rv$click_history <- c(rv$click_history, idx) } else { rv$click_history <- rv$click_history[rv$click_history != idx] }
        rv$show_error <- FALSE 
      } 
    } 
  })

  output$selection_warning <- renderUI({ if (rv$show_error) div(class="error-msg", "Please select at least one rectangle to continue.") })
  output$conf_warning <- renderUI({ if (rv$show_error) div(class="error-msg", "Please select your confidence level.") })

  output$dist_plot <- renderPlot({ 
    req(rv$current_data)
    ggplot(rv$current_data, aes(x = display_pos, y = height, fill = selected)) + 
      geom_bar(stat = "identity", width = 0.8, color = "transparent") + 
      scale_fill_manual(values = c("FALSE" = "#dcdde1", "TRUE" = "#3498db")) + 
      theme_void() + ylim(0, 100) + theme(legend.position = "none") 
  })

  observeEvent(input$confirm_btn, { if (sum(rv$current_data$selected) > 0) { rv$phase <- "certainty"; rv$show_error <- FALSE } else { rv$show_error <- TRUE } })

  observeEvent(input$next_btn, { 
    if (is.null(input$conf_score)) { rv$show_error <- TRUE } 
    else { 
      duration <- as.numeric(difftime(Sys.time(), rv$start_time, units = "secs")); trial_info <- rv$trial_list[rv$trial, ]; all_data <- rv$current_data
      pres_ranks <- paste(all_data$size_rank, collapse = ","); pres_heights <- paste(round(all_data$height, 2), collapse = ",")
      sel_ranks <- paste(all_data$size_rank[rv$click_history], collapse = ","); sel_heights <- paste(round(all_data$height[rv$click_history], 2), collapse = ",")
      sel_pos <- paste(rv$click_history, collapse = ",")
      val_mean_sel <- ifelse(length(rv$click_history) > 0, mean(all_data$height[rv$click_history]), NA)
      val_min_sel <- ifelse(length(rv$click_history) > 0, min(all_data$height[rv$click_history]), NA)

      res <- data.frame(p_id = rv$part_id, linguistic_form = rv$condition, age = rv$age, sex = rv$sex, nationality = rv$nationality, dist_type = trial_info$shape, pres_order = trial_info$order, set_size = trial_info$size, trial_num = rv$trial, time_sec = round(duration, 2), confidence = input$conf_score, mean_total = mean(all_data$height), sd_total = sd(all_data$height), median_total = median(all_data$height), count_sel = length(rv$click_history), mean_sel = val_mean_sel, min_height_sel = val_min_sel, presentation_ranks = pres_ranks, presentation_heights = pres_heights, selection_ranks = sel_ranks, selection_heights = sel_heights, selection_positions = sel_pos)

      rv$results <- rbind(rv$results, res)

      donnees_json <- jsonlite::toJSON(as.list(res), auto_unbox = TRUE)

      url_supabase <- "https://qxtwohbxebliooeaypez.supabase.co/rest/v1/data_tall_tallest" 
      cle_supabase <- "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InF4dHdvaGJ4ZWJsaW9vZWF5cGV6Iiwicm9sZSI6ImFub24iLCJpYXQiOjE3Nzk1NjgwMTcsImV4cCI6MjA5NTE0NDAxN30.OKqzq8_li-YX5oKuK7VbpDCzPtsQK5kBHlE08M43QeY"

      session$sendCustomMessage("send_data_to_supabase", list(url = url_supabase, apikey = cle_supabase, data = donnees_json)) 

      if (rv$trial < nrow(rv$trial_list)) { 
        rv$trial <- rv$trial + 1; rv$current_data <- NULL; rv$phase = "selection"; updateRadioButtons(session, "conf_score", selected = character(0)) 
      } else { 
        rv$phase <- "end"
      } 
    } 
  })
}
shinyApp(ui, server)
